package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := num()
	// Membership flips with every occurrence: the set holds labels seen an odd number of times.
	odd := map[int64]bool{}
	for i := int64(0); i < n; i++ {
		v := num()
		if odd[v] {
			delete(odd, v)
		} else {
			odd[v] = true
		}
	}
	fmt.Println(len(odd))
}
